let language=localStorage.getItem('dlr-language')||'en';
const tr=s=>language==='es'?(ES[s]||s):s;
function translate(){document.documentElement.lang=language;$('language').value=language;document.querySelectorAll('[data-t]').forEach(e=>e.textContent=tr(e.dataset.t));$('authButton').textContent=tr(user?'Log out':'Log in');}
function fresh(){return {format:FORMAT,language,saturdayLocked:false,config:{bracketBuyin:50,bracketFirst:250,bracketSecond:100,scratchBracketBuyin:50,scratchBracketFirst:250,scratchBracketSecond:100,satHighBuyin:50,satHighPayout:500,sunHighBuyin:50,sunHighPayout:500,doublesBuyin:50,doublesFirst:500,doublesSecond:300,doublesThird:200},bowlers:[],brackets:{satEarly:[],satLate:[],sunday:[],scratchEarly:[],scratchLate:[],scratchSunday:[]},teams:[],generated:false};}
const blankBrackets=()=>Object.fromEntries(Object.keys(WINDOWS).map(key=>[key,[]]));
function normalize(saved){const defaults=fresh();return{...defaults,...saved,language:saved.language||language,config:{...defaults.config,...saved.config},brackets:{...defaults.brackets,...saved.brackets},bowlers:(saved.bowlers||[]).map(b=>({...b,saturdayPaid:b.saturdayPaid??b.paid??false,sundayPaid:b.sundayPaid??false,events:{satEarly:0,satLate:0,sunday:0,scratchEarly:0,scratchLate:0,scratchSunday:0,satHigh:false,sunHigh:false,doubles:false,...b.events},scores:Array.from({length:7},(_,i)=>b.scores?.[i]??null)}))};}
const newClient=()=>createClient(cfg.url,{auth:{persistSession:true,autoRefreshToken:true,fetchOptions:{credentials:'include',cache:'no-store'}}});
let client=newClient(),user=null,role='user',competition=null,state=fresh(),editing=null,saveTimer=null,saving=false,queued=false,needsSessionReset=false;
async function resetExpiredSession(){if(!needsSessionReset)return;try{await client.auth.signOut();}catch{}client=newClient();user=null;needsSessionReset=false;translate();}
async function token(){let r=await client.auth.token();if(r.error||!r.data?.token){const restored=await client.auth.getSession();if(restored.data?.user){user=restored.data.user;r=await client.auth.token();}}if(r.error||!r.data?.token)throw new Error('Session expired. Log in again.');return r.data.token;}
async function api(path,method='GET',body){const auth=user?{'authorization':'Bearer '+await token()}:{};const r=await fetch(cfg.apiUrl+path,{method,headers:{'content-type':'application/json',...auth},body:body===undefined?undefined:JSON.stringify(body)}),data=await r.json();if(!r.ok)throw new Error(data.error||'Request failed');return data;}
function show(which){['authView','setupView','managerView','viewerView'].forEach(x=>$(x).classList.toggle('hidden',x!==which));}
function notice(s,error=false){$('notice').textContent=s;$('notice').classList.toggle('hidden',!s);$('notice').style.borderColor=error?'#bd2436':'';}
function maxBrackets(bowlers,prop){const pool=bowlers.map(b=>({id:b.id,limit:Math.max(0,Math.floor(Number(b.events?.[prop])||0)),assigned:0}));if(pool.filter(x=>x.limit).length<8)return 0;let low=0,high=Math.floor(pool.reduce((n,x)=>n+x.limit,0)/8);while(low<high){const mid=Math.ceil((low+high)/2);if(pool.reduce((n,x)=>n+Math.min(x.limit,mid),0)>=8*mid)low=mid;else high=mid-1;}return low;}
const pairKey=(a,b)=>[a,b].sort().join('|');
function allPairs(ids){if(!ids.length)return[[]];const [a,...rest]=ids,out=[];for(let i=0;i<rest.length;i++){for(const tail of allPairs(rest.filter((_,j)=>j!==i)))out.push([[a,rest[i]],...tail]);}return out;}
function seed(ids,opponents){const options=allPairs(ids),best=Math.min(...options.map(ps=>ps.reduce((n,[a,b])=>n+(opponents.get(pairKey(a,b))||0),0))),choice=options.filter(ps=>ps.reduce((n,[a,b])=>n+(opponents.get(pairKey(a,b))||0),0)===best)[Math.floor(Math.random()*options.filter(ps=>ps.reduce((n,[a,b])=>n+(opponents.get(pairKey(a,b))||0),0)===best).length)];choice.forEach(([a,b])=>opponents.set(pairKey(a,b),(opponents.get(pairKey(a,b))||0)+1));return choice.flat();}
function buildBrackets(bowlers,prop,sharedGroups=new Map(),opponents=new Map()){const count=maxBrackets(bowlers,prop);if(!count)return[];const pool=bowlers.map(b=>({id:b.id,limit:Math.min(count,Math.max(0,Math.floor(Number(b.events?.[prop])||0))),assigned:0}));for(let i=0;i<count*8;i++){const eligible=pool.filter(x=>x.assigned<x.limit).sort((a,b)=>(a.assigned/a.limit)-(b.assigned/b.limit)||Math.random()-.5);eligible[0].assigned++;}const result=Array.from({length:count},()=>[]);pool.sort((a,b)=>b.assigned-a.assigned||Math.random()-.5).forEach(p=>{for(let n=0;n<p.assigned;n++){const slots=result.map((ids,i)=>({ids,i})).filter(x=>x.ids.length<8&&!x.ids.includes(p.id)).sort((a,b)=>a.ids.reduce((n,x)=>n+(sharedGroups.get(pairKey(p.id,x))||0),0)-b.ids.reduce((n,x)=>n+(sharedGroups.get(pairKey(p.id,x))||0),0)||a.ids.length-b.ids.length);if(!slots[0])throw new Error('Could not place all bracket entries.');slots[0].ids.forEach(x=>sharedGroups.set(pairKey(p.id,x),(sharedGroups.get(pairKey(p.id,x))||0)+1));slots[0].ids.push(p.id);}});return result.map(ids=>seed(ids,opponents));}
const bowler=id=>state.bowlers.find(b=>b.id===id),has=(b,g)=>{const raw=b?.scores?.[g-1];return raw!==null&&raw!==''&&raw!==undefined&&Number.isFinite(Number(raw));},score=(b,g,withHandicap=true)=>has(b,g)?Number(b.scores[g-1])+(withHandicap?Number(b.handicap||0):0):null;
function duel(ids,game,scratch=false){const players=ids.map(bowler).filter(Boolean);if(players.length<2||players.some(b=>!has(b,game)))return null;const high=Math.max(...players.map(b=>score(b,game,!scratch))),w=players.filter(b=>score(b,game,!scratch)===high);return w.length===1?w[0].id:null;}
function bracketResult(ids,key){const games=WINDOWS[key],scratch=SCRATCH_KEYS.has(key),r1=[];for(let i=0;i<8;i+=2)r1.push(duel(ids.slice(i,i+2),games[0],scratch));const r2=[duel(r1.slice(0,2),games[1],scratch),duel(r1.slice(2,4),games[1],scratch)],winner=duel(r2,games[2],scratch);if(!winner)return null;return{winner,second:r2.find(x=>x&&x!==winner)||null,r1,r2};}
function bracketAwards(){const out=[];for(const key of Object.keys(WINDOWS))(state.brackets[key]||[]).forEach((ids,i)=>{const r=bracketResult(ids,key);if(!r)return;const scratch=SCRATCH_KEYS.has(key),first=scratch?state.config.scratchBracketFirst:state.config.bracketFirst,second=scratch?state.config.scratchBracketSecond:state.config.bracketSecond;out.push({id:r.winner,category:key,description:`${TITLES[key]} #${i+1} · 1st`,amount:cents(first)});if(r.second)out.push({id:r.second,category:key,description:`${TITLES[key]} #${i+1} · 2nd`,amount:cents(second)});});return out;}
function rankedAwards(entries,value,places,description,category){const sorted=entries.filter(x=>Number.isFinite(value(x))).sort((a,b)=>value(b)-value(a)||a.name.localeCompare(b.name)),out=[];for(let i=0;i<sorted.length&&i<places.length;){let end=i+1;while(end<sorted.length&&value(sorted[end])===value(sorted[i]))end++;const pool=places.slice(i,Math.min(end,places.length)).reduce((n,x)=>n+cents(x),0),share=Math.floor(pool/(end-i));for(let j=i;j<end;j++)out.push({id:sorted[j].id,category,description:`${description} · ${i+1}${end-i>1?' tie':''} (${value(sorted[j])})`,amount:share+(j-i<pool%(end-i)?1:0)});i=end;}return out;}
function highAwards(){const sat=state.bowlers.filter(b=>b.events.satHigh&&[1,2,3,4].every(g=>has(b,g))),sun=state.bowlers.filter(b=>b.events.sunHigh&&[5,6,7].every(g=>has(b,g)));return[...rankedAwards(sat,b=>Math.max(...[1,2,3,4].map(g=>score(b,g))),[state.config.satHighPayout],'Saturday High Game','satHigh'),...rankedAwards(sun,b=>Math.max(...[5,6,7].map(g=>score(b,g))),[state.config.sunHighPayout],'Sunday High Game','sunHigh')];}
function validTeams(){return state.teams.map((ids,index)=>({id:'team-'+index,ids,players:ids.map(bowler)})).filter(t=>t.players.length===2&&t.players.every(Boolean));}
function teamSeries(t){return t.players.every(b=>[1,2,3,4,5,6,7].every(g=>has(b,g)))?t.players.reduce((n,b)=>n+[1,2,3,4,5,6,7].reduce((s,g)=>s+score(b,g),0),0):NaN;}
function doublesAwards(){return rankedAwards(validTeams(),teamSeries,[state.config.doublesFirst,state.config.doublesSecond,state.config.doublesThird],'Doubles 7-game series','doubles').flatMap(a=>{const team=validTeams().find(t=>t.id===a.id),half=Math.floor(a.amount/2);return team.players.map((b,i)=>({...a,id:b.id,description:a.description+' · '+team.players.map(p=>p.name).join(' & '),amount:half+(i===0?a.amount%2:0)}));});}
function awards(){return[...bracketAwards(),...highAwards(),...doublesAwards()];}
function assigned(key,bid){return (state.brackets[key]||[]).reduce((n,ids)=>n+ids.filter(x=>x===bid).length,0);}
function charges(b){const c=[];for(const key of Object.keys(WINDOWS)){const n=assigned(key,b.id),price=SCRATCH_KEYS.has(key)?state.config.scratchBracketBuyin:state.config.bracketBuyin;if(n)c.push({label:`${TITLES[key]}: ${n} × $${Number(price).toFixed(2)}`,amount:n*cents(price),day:SUNDAY_KEYS.includes(key)?'sunday':'saturday'});}if(b.events.satHigh)c.push({label:`Saturday High Game: $${Number(state.config.satHighBuyin).toFixed(2)}`,amount:cents(state.config.satHighBuyin),day:'saturday'});if(b.events.sunHigh)c.push({label:`Sunday High Game: $${Number(state.config.sunHighBuyin).toFixed(2)}`,amount:cents(state.config.sunHighBuyin),day:'sunday'});const teamCount=state.teams.filter(ids=>ids.includes(b.id)).length;if(teamCount)c.push({label:`Doubles: ${teamCount} × $${Number(state.config.doublesBuyin).toFixed(2)}`,amount:teamCount*cents(state.config.doublesBuyin),day:'saturday'});return c;}
function personal(b){const cs=charges(b),wins=awards().filter(a=>a.id===b.id),saturdayDue=cs.filter(x=>x.day==='saturday').reduce((n,x)=>n+x.amount,0),sundayDue=cs.filter(x=>x.day==='sunday').reduce((n,x)=>n+x.amount,0),due=saturdayDue+sundayDue,won=wins.reduce((n,x)=>n+x.amount,0),outstanding=(b.saturdayPaid?0:saturdayDue)+(b.sundayPaid?0:sundayDue);return{id:b.id,name:b.name,paid:!!b.saturdayPaid&&!!b.sundayPaid,saturdayPaid:!!b.saturdayPaid,sundayPaid:!!b.sundayPaid,charges:cs,winnings:wins,saturdayDue,sundayDue,due,won,outstanding,settlement:won-outstanding};}
function snapshot(){const allAwards=awards(),people=state.bowlers.map(personal);return{results:{format:FORMAT,bowlers:state.bowlers,brackets:state.brackets,teams:state.teams,config:state.config,awards:allAwards},personal:state.bowlers.filter(b=>b.email).map(b=>({email:b.email,data:personal(b)})),people};}
function scheduleSave(){queued=true;$('saveState').textContent='Changes not saved yet.';clearTimeout(saveTimer);saveTimer=setTimeout(()=>void save().catch(()=>{}),500);}
async function save(){if(saving||!queued||!competition)return;saving=true;queued=false;$('saveState').textContent='Saving…';try{const snap=snapshot();await api('/save?id='+encodeURIComponent(competition.id),'POST',{state,results:snap.results,personal:snap.personal,eventDate:new Date().toLocaleDateString('en-CA')});$('saveState').textContent=queued?'Saving latest changes…':'Saved to Neon.';}catch(e){queued=true;$('saveState').textContent='Could not save: '+e.message;throw e;}finally{saving=false;if(queued)saveTimer=setTimeout(()=>void save().catch(()=>{}),800);}}
async function flushSave(){clearTimeout(saveTimer);while(saving)await new Promise(resolve=>setTimeout(resolve,50));if(queued)await save();while(saving||queued){while(saving)await new Promise(resolve=>setTimeout(resolve,50));if(queued)await save();}}
const configDefs=[['bracketBuyin','Handicap bracket buy-in, per entry'],['bracketFirst','Handicap bracket 1st place'],['bracketSecond','Handicap bracket 2nd place'],['scratchBracketBuyin','Scratch bracket buy-in, per entry'],['scratchBracketFirst','Scratch bracket 1st place'],['scratchBracketSecond','Scratch bracket 2nd place'],['satHighBuyin','Saturday High Game buy-in'],['satHighPayout','Saturday High Game payout'],['sunHighBuyin','Sunday High Game buy-in'],['sunHighPayout','Sunday High Game payout'],['doublesBuyin','Doubles buy-in, per bowler/team'],['doublesFirst','Doubles 1st place'],['doublesSecond','Doubles 2nd place'],['doublesThird','Doubles 3rd place']];
const eventDefs=[['satEarly','Handicap Saturday Brackets · Games 1–3'],['satLate','Handicap Saturday Brackets · Games 2–4'],['sunday','Handicap Sunday Brackets · Games 1–3'],['scratchEarly','Scratch Saturday Brackets · Games 1–3'],['scratchLate','Scratch Saturday Brackets · Games 2–4'],['scratchSunday','Scratch Sunday Brackets · Games 1–3']];
function renderConfig(){ $('configForm').innerHTML=configDefs.map(([k,label])=>`<label>${esc(tr(label))} ($)<input name="${k}" type="number" min="0" step=".01" value="${state.config[k]}" required></label>`).join(''); }
function renderEventFields(b={events:{}}){$('eventFields').innerHTML=eventDefs.map(([k,label])=>`<div class="event-box"><label><input type="checkbox" data-event="${k}" ${b.events[k]>0?'checked':''}> ${esc(label)}</label><input data-count="${k}" type="number" min="1" max="99" value="${b.events[k]||1}" ${b.events[k]>0?'':'disabled'}></div>`).join('')+`<div class="event-box"><label><input type="checkbox" data-flag="satHigh" ${b.events.satHigh?'checked':''}> ${esc(tr('Saturday High Game'))}</label></div><div class="event-box"><label><input type="checkbox" data-flag="sunHigh" ${b.events.sunHigh?'checked':''}> ${esc(tr('Sunday High Game'))}</label></div><div class="event-box"><label><input type="checkbox" data-flag="doubles" ${b.events.doubles?'checked':''}> ${esc(tr('Doubles'))}</label></div>`;}
function renderRoster(){$('rosterRows').innerHTML=alphabetical(state.bowlers).map(b=>`<tr><td><strong>${esc(b.name)}</strong>${b.email?`<br><small>${esc(b.email)}</small>`:''}</td><td>${b.handicap}</td><td>${b.events.satEarly||0} / ${b.events.satLate||0} / ${b.events.sunday||0}</td><td>${b.events.scratchEarly||0} / ${b.events.scratchLate||0} / ${b.events.scratchSunday||0}</td><td>${b.events.satHigh?'Sat ':''}${b.events.sunHigh?'Sun':''}</td><td>${state.teams.filter(x=>x.includes(b.id)).length}</td><td><label><input type="checkbox" data-paid-day="saturday" data-paid-id="${b.id}" ${b.saturdayPaid?'checked':''}> ${tr('Paid')}</label></td><td><label><input type="checkbox" data-paid-day="sunday" data-paid-id="${b.id}" ${b.sundayPaid?'checked':''}> ${tr('Paid')}</label></td><td><button class="secondary" data-edit="${b.id}">${tr('Edit')}</button> <button class="danger" data-remove="${b.id}">${tr('Remove')}</button></td></tr>`).join('')||'<tr><td colspan="9">No bowlers registered.</td></tr>';}
function bracketDiagram(ids,key){const games=WINDOWS[key],scratch=SCRATCH_KEYS.has(key),r1=[];for(let i=0;i<8;i+=2)r1.push(duel(ids.slice(i,i+2),games[0],scratch));const r2=[duel(r1.slice(0,2),games[1],scratch),duel(r1.slice(2,4),games[1],scratch)],winner=duel(r2,games[2],scratch);const slot=(bid,won,lost,game)=>{const b=bowler(bid);return`<div class="slot ${won?'win':lost?'lose':'pending'}">${esc(b?.name||'Pending')}${b&&has(b,game)?` <small>${score(b,game,!scratch)}</small>`:''}</div>`},matches=(players,winners,game)=>players.reduce((html,_,i)=>i%2?html:html+`<div class="match-box">${slot(players[i],winners[Math.floor(i/2)]===players[i],!!winners[Math.floor(i/2)]&&winners[Math.floor(i/2)]!==players[i],game)}${slot(players[i+1],winners[Math.floor(i/2)]===players[i+1],!!winners[Math.floor(i/2)]&&winners[Math.floor(i/2)]!==players[i+1],game)}</div>`,'');return`<div class="bracket-diagram"><div class="bracket-round"><h4>Game ${games[0]}</h4>${matches(ids,r1,games[0])}</div><div class="bracket-round"><h4>Game ${games[1]} · Semifinal</h4>${matches(r1,r2,games[1])}</div><div class="bracket-round"><h4>Game ${games[2]} · Final</h4><div class="match-box">${matches(r2,[winner],games[2])}</div></div><div class="bracket-round round-winner"><h4>Winner</h4>${slot(winner,!!winner,false,games[2])}</div></div>`;}
function renderBrackets(){$('bracketLists').innerHTML=Object.keys(WINDOWS).map(key=>`<div class="bracket-group"><h2>${esc(TITLES[key])}</h2>${state.brackets[key].length?state.brackets[key].map((ids,i)=>{const result=bracketResult(ids,key);return`<div class="card bracket-card"><h3>Bracket #${i+1}</h3>${bracketDiagram(ids,key)}${result?`<p><strong>1st:</strong> ${esc(bowler(result.winner)?.name)} · <strong>2nd:</strong> ${esc(bowler(result.second)?.name)}</p>`:'<p>No results yet.</p>'}</div>`}).join(''):'<div class="card">No brackets generated.</div>'}`).join('');const unused=state.bowlers.flatMap(b=>eventDefs.map(([key])=>{const n=(b.events[key]||0)-assigned(key,b.id);return n>0?`${b.name}: ${n} unused ${TITLES[key]}`:null})).filter(Boolean);$('bracketNotice').innerHTML=unused.length?`<p class="notice">Unused willingness is not charged: ${esc(unused.join(' · '))}</p>`:'';}
function dayBracketPayouts(keys,highCategory){const totals=new Map(),rowFor=bid=>{const row=totals.get(bid)||{id:bid,first:0,second:0,high:0,amount:0};totals.set(bid,row);return row};for(const key of keys)(state.brackets[key]||[]).forEach(ids=>{const result=bracketResult(ids,key);if(!result)return;const scratch=SCRATCH_KEYS.has(key),first=cents(scratch?state.config.scratchBracketFirst:state.config.bracketFirst),second=cents(scratch?state.config.scratchBracketSecond:state.config.bracketSecond),winner=rowFor(result.winner);winner.first++;winner.amount+=first;if(result.second){const runner=rowFor(result.second);runner.second++;runner.amount+=second}});for(const award of highAwards().filter(a=>a.category===highCategory)){const row=rowFor(award.id);row.high+=award.amount;row.amount+=award.amount}return alphabetical([...totals.values()].map(row=>({...row,name:bowler(row.id)?.name||'Unknown'})));}
function renderDayResults(title,keys,highCategory){const payoutRows=dayBracketPayouts(keys,highCategory),payouts=payoutRows.length?`<div class="card"><h3>${esc(tr('Daily payout summary'))}</h3><div class="table-wrap"><table><thead><tr><th>${esc(tr('Bowler'))}</th><th>${esc(tr('First places'))}</th><th>${esc(tr('Second places'))}</th><th>${esc(tr('High Game payout'))}</th><th>${esc(tr('Total payout'))}</th></tr></thead><tbody>${payoutRows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${r.first}</td><td>${r.second}</td><td class="money">${money(r.high)}</td><td class="money"><strong>${money(r.amount)}</strong></td></tr>`).join('')}</tbody></table></div><p><small>${esc(tr('Doubles spans all seven games and remains in the full Reports & payouts summary.'))}</small></p></div>`:`<div class="card"><p>${esc(tr('No completed payouts yet.'))}</p></div>`;const brackets=keys.map(key=>`<div class="bracket-group"><h2>${esc(tr(TITLES[key]))}</h2>${(state.brackets[key]||[]).length?(state.brackets[key]||[]).map((ids,i)=>{const result=bracketResult(ids,key);return`<div class="card bracket-card"><h3>Bracket #${i+1}</h3>${bracketDiagram(ids,key)}${result?`<p><strong>${esc(tr('1st'))}:</strong> ${esc(bowler(result.winner)?.name)} · <strong>${esc(tr('2nd'))}:</strong> ${esc(bowler(result.second)?.name)}</p>`:`<p>${esc(tr('No results yet.'))}</p>`}</div>`}).join(''):`<div class="card"><p>${esc(tr('No brackets generated.'))}</p></div>`}`).join('');return`<section class="day-results"><div class="card day-results-heading"><h2>${esc(tr(title))}</h2></div>${payouts}${brackets}</section>`;}
function renderWeekendResults(){$('weekendResults').innerHTML=renderDayResults('Saturday results',SATURDAY_KEYS,'satHigh')+renderDayResults('Sunday results',SUNDAY_KEYS,'sunHigh');}
function bracketHistory(keys){const groups=new Map(),opponents=new Map();for(const key of keys)for(const ids of state.brackets[key]||[]){for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++)groups.set(pairKey(ids[i],ids[j]),(groups.get(pairKey(ids[i],ids[j]))||0)+1);for(let i=0;i<ids.length;i+=2)if(ids[i+1])opponents.set(pairKey(ids[i],ids[i+1]),(opponents.get(pairKey(ids[i],ids[i+1]))||0)+1)}return{groups,opponents};}
const hasSaturdayScores=()=>state.bowlers.some(b=>(b.scores||[]).slice(0,4).some(score=>score!==null&&score!==''&&score!==undefined));
function resetBracketsAfterRosterChange(){if(state.saturdayLocked||hasSaturdayScores()){for(const key of SUNDAY_KEYS)state.brackets[key]=[];state.generated=SATURDAY_KEYS.some(key=>state.brackets[key].length)}else{state.brackets=blankBrackets();state.generated=false;}}
function renderBracketResultsExport(){const bracketKeys=Object.keys(WINDOWS),participants=alphabetical(state.bowlers.map(b=>{const played=bracketKeys.reduce((n,key)=>n+assigned(key,b.id),0),won=bracketKeys.reduce((n,key)=>n+(state.brackets[key]||[]).filter(ids=>bracketResult(ids,key)?.winner===b.id).length,0);return{...b,played,won};}).filter(b=>b.played));const summary=participants.map(b=>`<tr><td>${esc(b.name)}</td><td>${b.played}</td><td>${b.won}</td></tr>`).join('');const diagrams=bracketKeys.map(key=>{const cards=(state.brackets[key]||[]).map((ids,i)=>{const result=bracketResult(ids,key);return`<article class="export-bracket"><h3>${esc(tr(TITLES[key]))} · Bracket #${i+1}</h3>${bracketDiagram(ids,key)}${result?`<p><strong>${esc(tr('1st'))}:</strong> ${esc(bowler(result.winner)?.name)} &nbsp; <strong>${esc(tr('2nd'))}:</strong> ${esc(bowler(result.second)?.name)}</p>`:'<p>'+esc(tr('No results yet.'))+'</p>'}</article>`}).join('');return cards?`<section class="export-group"><h2>${esc(tr(TITLES[key]))}</h2>${cards}</section>`:''}).join('');$('bracketResultsPrint').innerHTML=`<div class="export-brand"><img src="../assets/brackets-logo.png?v=20260922" alt="Brackets by ProDrillOS"><div><div class="eyebrow">DE LA ROSA MASTERS</div><h1>${esc(tr('Bracket results'))}</h1><p>${new Date().toLocaleDateString(language==='es'?'es-MX':'en-US',{dateStyle:'long'})}</p></div></div><section class="export-summary"><h2>${esc(tr('Bracket participation summary'))}</h2><table><thead><tr><th>${esc(tr('Bowler'))}</th><th>${esc(tr('Brackets played'))}</th><th>${esc(tr('Brackets won'))}</th></tr></thead><tbody>${summary}</tbody></table></section>${diagrams}`;}
function printBracketResults(){renderBracketResultsExport();document.body.classList.add('bracket-results-print');$('bracketResultsPrint').setAttribute('aria-hidden','false');const cleanup=()=>{document.body.classList.remove('bracket-results-print');$('bracketResultsPrint').setAttribute('aria-hidden','true')};window.addEventListener('afterprint',cleanup,{once:true});window.print();}
function printPayoutReport(){document.body.classList.add('payout-report-print');const cleanup=()=>document.body.classList.remove('payout-report-print');window.addEventListener('afterprint',cleanup,{once:true});window.print();}
function requiredGames(b){if(b.events.doubles)return new Set([1,2,3,4,5,6,7]);const games=new Set();for(const key of Object.keys(WINDOWS))if(b.events[key])WINDOWS[key].forEach(g=>games.add(g));if(b.events.satHigh)[1,2,3,4].forEach(g=>games.add(g));if(b.events.sunHigh)[5,6,7].forEach(g=>games.add(g));return games;}
function renderScores(){$('scoreHead').innerHTML='<tr><th>Bowler</th>'+[1,2,3,4].map(g=>`<th>Sat G${g}</th>`).join('')+[1,2,3].map(g=>`<th class="score-separator">Sun G${g}</th>`).join('')+'</tr>';$('scoreRows').innerHTML=alphabetical(state.bowlers).map(b=>{const required=requiredGames(b);return`<tr><td><strong>${esc(b.name)}</strong><br><small>+${b.handicap}</small></td>${[1,2,3,4,5,6,7].map((g,i)=>`<td class="${g===5?'score-separator':''}">${required.has(g)?state.saturdayLocked&&g<=4?`<span class="locked-score">${b.scores[i]??'—'} <span aria-label="Locked">🔒</span></span>`:`<input aria-label="${esc(b.name)} game ${g}" data-score="${b.id}" data-game="${i}" type="number" min="0" max="300" value="${b.scores[i]??''}">`:'<span class="not-required">—</span>'}</td>`).join('')}</tr>`}).join('');const locked=!!state.saturdayLocked;$('lockSaturday').disabled=locked;$('lockSaturday').textContent=tr(locked?'Saturday scores locked':'Lock Saturday scores');$('saturdayLockStatus').classList.toggle('hidden',!locked);$('saturdayLockStatus').textContent=locked?tr('Saturday games 1–4 and their brackets are permanently protected. Only Sunday scores can be added.'):'';$('generateBrackets').disabled=locked;}
function standingCard(title,players,value,awardList){const sorted=players.filter(x=>Number.isFinite(value(x))).sort((a,b)=>value(b)-value(a));return`<div class="card"><h2>${esc(title)}</h2>${sorted.length?`<ol>${sorted.map(x=>`<li class="team-rank"><strong>${esc(x.name||x.players.map(p=>p.name).join(' & '))}</strong> — ${value(x)}</li>`).join('')}</ol><p>${awardList.map(a=>`${esc(bowler(a.id)?.name||'')}: ${money(a.amount)}`).join('<br>')}</p>`:'<p>No results yet.</p>'}</div>`;}
function renderHigh(){const sat=state.bowlers.filter(b=>b.events.satHigh),sun=state.bowlers.filter(b=>b.events.sunHigh);$('highResults').innerHTML=standingCard(tr('Saturday High Game'),sat,b=>[1,2,3,4].every(g=>has(b,g))?Math.max(...[1,2,3,4].map(g=>score(b,g))):NaN,highAwards().filter(a=>a.category==='satHigh'))+standingCard(tr('Sunday High Game'),sun,b=>[5,6,7].every(g=>has(b,g))?Math.max(...[5,6,7].map(g=>score(b,g))):NaN,highAwards().filter(a=>a.category==='sunHigh'));}
function renderTeams(){$('bowlerOptions').innerHTML=alphabetical(state.bowlers.filter(b=>b.events.doubles)).map(b=>`<option value="${esc(b.name)}"></option>`).join('');const teams=validTeams();$('teamResults').innerHTML=`<div class="card"><h2>${tr('Doubles')} · ${tr('Doubles 7-game series')}</h2>${state.teams.length?`<ol>${state.teams.map((ids,i)=>{const t=teams.find(x=>x.id==='team-'+i);return`<li class="team-rank"><strong>${ids.map(x=>esc(bowler(x)?.name||'Unknown')).join(' &amp; ')}</strong> — ${t&&Number.isFinite(teamSeries(t))?teamSeries(t):'—'} <button class="danger" data-remove-team="${i}">${tr('Remove')}</button></li>`}).join('')}</ol>`:'<p>No teams registered.</p>'}</div>`;}
function renderReports(){const rows=alphabetical(state.bowlers).map(personal);$('reportRows').innerHTML=rows.map(r=>{const hasScores=bowler(r.id)?.scores?.some(score=>score!==null&&score!==''&&score!==undefined);return`<tr class="${hasScores?'':'no-entered-scores'}"><td><strong>${esc(r.name)}</strong></td><td>${r.charges.map(c=>esc(c.label)).join('<br>')||'—'}</td><td class="money">${money(r.due)}</td><td>${tr(r.saturdayPaid?'Yes':'No')}<br><small>${money(r.saturdayDue)}</small></td><td>${tr(r.sundayPaid?'Yes':'No')}<br><small>${money(r.sundayDue)}</small></td><td class="money balance-negative">${money(r.outstanding)}</td><td>${r.winnings.map(w=>`${esc(w.description)} ${money(w.amount)}`).join('<br>')||'—'}</td><td class="money">${money(r.won)}</td><td class="money ${r.settlement>0?'balance-positive':r.settlement<0?'balance-negative':'balance-zero'}">${r.settlement>=0?'+':''}${money(r.settlement)}</td></tr>`}).join('');const totals=rows.reduce((x,r)=>({due:x.due+r.due,paid:x.paid+(r.saturdayPaid?r.saturdayDue:0)+(r.sundayPaid?r.sundayDue:0),out:x.out+r.outstanding,won:x.won+r.won,settle:x.settle+r.settlement}),{due:0,paid:0,out:0,won:0,settle:0});$('reportTotals').innerHTML=[['Total charges',totals.due],['Payments received',totals.paid],['Outstanding',totals.out],['Total winnings',totals.won],['Total to settle now',totals.settle]].map(([k,v])=>`<div>${esc(k)}<strong>${v===totals.settle&&v>0?'+':''}${money(v)}</strong></div>`).join('');}
function viewerDiagram(ids,key,data){const byId=new Map(data.bowlers.map(b=>[b.id,b])),games=WINDOWS[key],scratch=SCRATCH_KEYS.has(key),vscore=(bid,g)=>{const b=byId.get(bid),raw=b?.scores?.[g-1];return raw===null||raw===''||raw===undefined?null:Number(raw)+(scratch?0:Number(b.handicap||0))},vduel=(players,g)=>{if(players.some(x=>!x||vscore(x,g)===null))return null;const high=Math.max(...players.map(x=>vscore(x,g))),w=players.filter(x=>vscore(x,g)===high);return w.length===1?w[0]:null},r1=[];for(let i=0;i<8;i+=2)r1.push(vduel(ids.slice(i,i+2),games[0]));const r2=[vduel(r1.slice(0,2),games[1]),vduel(r1.slice(2,4),games[1])],winner=vduel(r2,games[2]);const slot=(bid,won,lost,g)=>`<div class="slot ${won?'win':lost?'lose':'pending'}">${esc(byId.get(bid)?.name||'Pending')}${bid&&vscore(bid,g)!==null?` <small>${vscore(bid,g)}</small>`:''}</div>`,matches=(players,winners,g)=>players.reduce((html,_,i)=>i%2?html:html+`<div class="match-box">${slot(players[i],winners[Math.floor(i/2)]===players[i],!!winners[Math.floor(i/2)]&&winners[Math.floor(i/2)]!==players[i],g)}${slot(players[i+1],winners[Math.floor(i/2)]===players[i+1],!!winners[Math.floor(i/2)]&&winners[Math.floor(i/2)]!==players[i+1],g)}</div>`,'');return`<div class="bracket-diagram"><div class="bracket-round"><h4>Game ${games[0]}</h4>${matches(ids,r1,games[0])}</div><div class="bracket-round"><h4>Game ${games[1]} · Semifinal</h4>${matches(r1,r2,games[1])}</div><div class="bracket-round"><h4>Game ${games[2]} · Final</h4>${matches(r2,[winner],games[2])}</div><div class="bracket-round round-winner"><h4>Winner</h4>${slot(winner,!!winner,false,games[2])}</div></div>`;}
function viewerPersonal(data,bowlerId){const b=data.bowlers.find(x=>x.id===bowlerId);if(!b)return null;const saturdayPaid=b.saturdayPaid??b.paid??false,sundayPaid=b.sundayPaid??false,cs=[];for(const key of Object.keys(WINDOWS)){const n=(data.brackets?.[key]||[]).reduce((sum,ids)=>sum+ids.filter(x=>x===b.id).length,0),price=SCRATCH_KEYS.has(key)?data.config.scratchBracketBuyin:data.config.bracketBuyin;if(n)cs.push({label:`${TITLES[key]}: ${n} × $${Number(price).toFixed(2)}`,amount:n*cents(price),day:SUNDAY_KEYS.includes(key)?'sunday':'saturday'});}if(b.events?.satHigh)cs.push({label:`Saturday High Game: $${Number(data.config.satHighBuyin).toFixed(2)}`,amount:cents(data.config.satHighBuyin),day:'saturday'});if(b.events?.sunHigh)cs.push({label:`Sunday High Game: $${Number(data.config.sunHighBuyin).toFixed(2)}`,amount:cents(data.config.sunHighBuyin),day:'sunday'});const teamCount=(data.teams||[]).filter(ids=>ids.includes(b.id)).length;if(teamCount)cs.push({label:`Doubles: ${teamCount} × $${Number(data.config.doublesBuyin).toFixed(2)}`,amount:teamCount*cents(data.config.doublesBuyin),day:'saturday'});const winnings=(data.awards||[]).filter(a=>a.id===b.id),saturdayDue=cs.filter(x=>x.day==='saturday').reduce((n,x)=>n+x.amount,0),sundayDue=cs.filter(x=>x.day==='sunday').reduce((n,x)=>n+x.amount,0),due=saturdayDue+sundayDue,won=winnings.reduce((n,x)=>n+Number(x.amount||0),0),outstanding=(saturdayPaid?0:saturdayDue)+(sundayPaid?0:sundayDue);return{id:b.id,name:b.name,paid:saturdayPaid&&sundayPaid,saturdayPaid,sundayPaid,charges:cs,winnings,saturdayDue,sundayDue,due,won,outstanding,settlement:won-outstanding};}
function renderViewer(data,personalData,selectedId=personalData?.id){
  const people=data?.bowlers||[];if(!data){$('viewerContent').innerHTML='<div class="card"><p>Results are not available yet.</p></div>';return;}
  const selected=people.find(b=>b.id===selectedId),visiblePeople=selected?[selected]:people;
  if(selected&&!personalData)personalData=viewerPersonal(data,selected.id);
  const chooser=`<div class="card"><h2>${tr('Your bowler')}</h2><p>${tr('Choose your bowler to see your balance, scores and only the brackets you are competing in.')}</p><div class="form-grid compact"><label>${tr('Bowler')}<select id="viewerBowler"><option value="">${tr('Choose a bowler')}</option>${people.slice().sort((a,b)=>a.name.localeCompare(b.name)).map(b=>`<option value="${esc(b.id)}" ${b.id===selectedId?'selected':''}>${esc(b.name)}</option>`).join('')}</select></label><button id="viewerSelect">${tr('Show my results')}</button></div><p id="viewerSelectStatus" class="error"></p></div>`;
  const personalCard=personalData?`<div class="card"><h2>${tr('Your balance')} — ${esc(personalData.name)}</h2><p>${personalData.charges.map(c=>`• ${esc(c.label)}: ${money(c.amount)}`).join('<br>')||'No charges'}</p><p><strong>${tr('Saturday due')}: ${money(personalData.saturdayDue||0)} · ${tr('Saturday paid')}: ${tr(personalData.saturdayPaid?'Yes':'No')}<br>${tr('Sunday due')}: ${money(personalData.sundayDue||0)} · ${tr('Sunday paid')}: ${tr(personalData.sundayPaid?'Yes':'No')}<br>Total: ${money(personalData.due)} · ${tr('Outstanding')}: ${money(personalData.outstanding)}</strong></p><p>${personalData.winnings.map(w=>`• ${esc(w.description)}: ${money(w.amount)}`).join('<br>')||'No winnings'}</p><h3 class="${personalData.settlement>0?'balance-positive':personalData.settlement<0?'balance-negative':'balance-zero'}">${tr('Settle now')}: ${personalData.settlement>=0?'+':''}${money(personalData.settlement)}</h3></div>`:'';
  const scores=selected?`<div class="card"><h2>${tr('Scores')} — ${esc(selected.name)}</h2><div class="table-wrap"><table><thead><tr><th>${tr('Bowler')}</th>${[1,2,3,4,5,6,7].map(g=>`<th>G${g}</th>`).join('')}</tr></thead><tbody>${visiblePeople.map(b=>`<tr><td>${esc(b.name)}<br><small>+${b.handicap}</small></td>${b.scores.map(x=>`<td>${x==null?'—':Number(x)+Number(b.handicap||0)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`:'';
  const brackets=selected?Object.keys(WINDOWS).map(key=>{const entries=(data.brackets?.[key]||[]).map((ids,index)=>({ids,index})).filter(x=>x.ids.includes(selected.id));return`<div class="bracket-group"><h2>${esc(TITLES[key])}</h2>${entries.length?entries.map(x=>`<div class="card bracket-card"><h3>Bracket #${x.index+1}</h3>${viewerDiagram(x.ids,key,data)}</div>`).join(''):`<div class="card"><p>${esc(selected.name)} is not entered in this bracket competition.</p></div>`}</div>`}).join(''):'';
  const teams=selected?(data.teams||[]).filter(ids=>ids.includes(selected.id)).map(ids=>ids.map(x=>people.find(b=>b.id===x)?.name||'Unknown').join(' & ')):[];
  const relatedAwards=(data.awards||[]).filter(a=>!selected||a.id===selected.id);
  $('viewerContent').innerHTML=`<div class="card viewer-hero"><h2>${NAME}</h2><p>Saturday: 4 games · Sunday: 3 games</p></div>${chooser}${personalCard}${scores}${brackets}${selected?`<div class="card"><h2>${tr('Doubles')}</h2>${teams.length?teams.map(esc).join('<br>'):'No Doubles teams.'}</div><div class="card"><h2>${tr('Payout summary')}</h2>${relatedAwards.map(a=>`${esc(a.description)} — ${money(a.amount)}`).join('<br>')||tr('No results yet.')}</div>`:''}`;
  $('viewerSelect').addEventListener('click',async()=>{const bowlerId=$('viewerBowler').value;if(!bowlerId){$('viewerSelectStatus').textContent=tr('Choose a bowler.');return;}try{$('viewerSelect').disabled=true;const linked=await api('/balance','POST',{competitionId:competition.id,bowlerId});renderViewer(data,linked.personal||viewerPersonal(data,bowlerId),bowlerId);translate();}catch(error){$('viewerSelectStatus').textContent=error.message;$('viewerSelect').disabled=false;}});translate();
}
function render(){state.language=language;renderConfig();renderEventFields(editing?bowler(editing):undefined);renderRoster();renderBrackets();renderScores();renderHigh();renderTeams();renderReports();if($('weekend').classList.contains('active'))renderWeekendResults();translate();}
function resetForm(){$('bowlerForm').reset();$('handicap').value=0;editing=null;$('bowlerHeading').textContent=tr('Register a bowler');$('saveBowler').textContent=tr('Add bowler');$('cancelEdit').classList.add('hidden');renderEventFields();}
async function enter(){const rows=await api('/competitions'),found=rows.find(c=>c.name.trim().toLocaleLowerCase()===NAME.toLocaleLowerCase());competition=found||null;if(!found){show(role==='superadmin'?'setupView':'viewerView');if(role!=='superadmin')$('viewerContent').innerHTML='<div class="card"><p>This tournament has not been created yet.</p></div>';return;}if(found.can_manage){const saved=await api('/state?id='+encodeURIComponent(found.id));if(saved&&saved.format!==FORMAT)throw new Error('This competition contains a different tournament format.');state=saved?normalize(saved):fresh();language=state.language||language;show('managerView');render();}else{const result=await api('/results?id='+encodeURIComponent(found.id));show('viewerView');renderViewer(result.results,result.personal,result.bowlerId);}}
async function identify(u){user=u||null;$('authButton').textContent=tr(user?'Log out':'Log in');if(!user){show('authView');translate();return;}role=(await api('/me')).role||'user';$('superAdminTools').classList.toggle('hidden',role!=='superadmin');await enter();translate();}

$('language').addEventListener('change',e=>{language=e.target.value;localStorage.setItem('dlr-language',language);if(state)state.language=language;translate();if(competition?.can_manage)scheduleSave();});
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const credentials={email:$('email').value.trim().toLowerCase(),password:$('password').value};await resetExpiredSession();let r=await client.auth.signIn.email(credentials);if(r.error&&/expired|session|refresh/i.test(r.error.message||String(r.error))){needsSessionReset=true;await resetExpiredSession();r=await client.auth.signIn.email(credentials);}if(r.error)throw r.error;$('password').value='';notice('');await identify(r.data.user);}catch(err){if(/expired|session|refresh/i.test(err.message||String(err)))needsSessionReset=true;notice(err.message,true);}});
$('authButton').addEventListener('click',async()=>{if(user){await client.auth.signOut();user=null;competition=null;show('authView');translate();}else show('authView');});
$('createTournament').addEventListener('click',async()=>{try{await api('/competitions','POST',{name:NAME,kind:'tournament'});await enter();notice('De La Rosa Masters created.');}catch(e){notice(e.message,true);}});
$('tabs').addEventListener('click',e=>{const b=e.target.closest('[data-tab]');if(!b)return;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('.panel').forEach(x=>x.classList.toggle('active',x.id===b.dataset.tab));render();});
$('configForm').addEventListener('submit',e=>{e.preventDefault();for(const [k] of configDefs)state.config[k]=Number(new FormData(e.target).get(k));scheduleSave();notice('Payout configuration saved.');renderReports();});
$('eventFields').addEventListener('change',e=>{if(e.target.dataset.event){const input=qs(`[data-count="${e.target.dataset.event}"]`);input.disabled=!e.target.checked;}});
$('bowlerForm').addEventListener('submit',e=>{e.preventDefault();const name=$('bowlerName').value.trim(),email=$('bowlerEmail').value.trim().toLowerCase();if(state.bowlers.some(b=>b.id!==editing&&b.name.toLowerCase()===name.toLowerCase()))return notice('A bowler with that name is already registered.',true);if(email&&state.bowlers.some(b=>b.id!==editing&&b.email===email))return notice('That email is already linked to another bowler.',true);const previous=bowler(editing),events={};eventDefs.forEach(([k])=>events[k]=qs(`[data-event="${k}"]`).checked?Number(qs(`[data-count="${k}"]`).value):0);['satHigh','sunHigh','doubles'].forEach(k=>events[k]=qs(`[data-flag="${k}"]`).checked);const b={id:editing||id(),name,email,handicap:Number($('handicap').value),paid:previous?.paid||false,saturdayPaid:previous?.saturdayPaid??previous?.paid??false,sundayPaid:previous?.sundayPaid??false,events,scores:previous?.scores||Array(7).fill(null)};if(previous)state.bowlers[state.bowlers.indexOf(previous)]=b;else state.bowlers.push(b);resetBracketsAfterRosterChange();resetForm();scheduleSave();render();notice(hasSaturdayScores()?'Bowler saved. Saturday brackets were preserved; generate Sunday brackets when ready.':'Bowler saved. Generate brackets after roster changes.');});
$('cancelEdit').addEventListener('click',resetForm);
$('rosterRows').addEventListener('click',e=>{const edit=e.target.closest('[data-edit]'),remove=e.target.closest('[data-remove]');if(edit){const b=bowler(edit.dataset.edit);editing=b.id;$('bowlerName').value=b.name;$('bowlerEmail').value=b.email;$('handicap').value=b.handicap;$('bowlerHeading').textContent=tr('Edit')+' '+b.name;$('saveBowler').textContent=tr('Save changes');$('cancelEdit').classList.remove('hidden');renderEventFields(b);scrollTo({top:$('bowlerForm').offsetTop,behavior:'smooth'});}if(remove){const b=bowler(remove.dataset.remove);if(!confirm('Remove '+b.name+'?'))return;state.bowlers=state.bowlers.filter(x=>x.id!==b.id);state.teams=state.teams.filter(x=>!x.includes(b.id));resetBracketsAfterRosterChange();scheduleSave();render();}});
$('rosterRows').addEventListener('change',e=>{if(!e.target.dataset.paidId)return;const b=bowler(e.target.dataset.paidId);if(e.target.dataset.paidDay==='saturday')b.saturdayPaid=e.target.checked;else b.sundayPaid=e.target.checked;b.paid=!!b.saturdayPaid&&!!b.sundayPaid;scheduleSave();renderReports();});
$('generateBrackets').addEventListener('click',async()=>{const button=$('generateBrackets');if(state.saturdayLocked)return notice('Saturday is locked. Use Generate Sunday brackets only.',true);if(hasSaturdayScores()&&SATURDAY_KEYS.some(key=>state.brackets[key].length)&&!confirm('This will replace the completed Saturday brackets. Use Generate Sunday brackets only to keep Saturday. Continue?'))return;try{button.disabled=true;const groups=new Map(),opponents=new Map();state.brackets=Object.fromEntries(Object.keys(WINDOWS).map(key=>[key,buildBrackets(state.bowlers,key,groups,opponents)]));state.generated=true;const total=Object.values(state.brackets).reduce((n,x)=>n+x.length,0);scheduleSave();render();notice(total+' complete eight-bowler brackets generated. Saving the complete draw to Neon…');await flushSave();const confirmed=await api('/state?id='+encodeURIComponent(competition.id)),matches=Object.keys(WINDOWS).every(key=>JSON.stringify(confirmed?.brackets?.[key]||[])===JSON.stringify(state.brackets[key]));if(!confirmed?.generated||!matches)throw new Error('Neon did not return the complete generated draw. Please keep this page open and try Generate all brackets again.');notice(total+' complete eight-bowler brackets generated and verified in Neon.');}catch(e){notice('The brackets were generated but could not be verified as saved: '+e.message,true);}finally{button.disabled=!!state.saturdayLocked;}});
$('generateSundayBrackets').addEventListener('click',async()=>{const button=$('generateSundayBrackets');try{button.disabled=true;const{groups,opponents}=bracketHistory(SATURDAY_KEYS),sunday={};for(const key of SUNDAY_KEYS)sunday[key]=buildBrackets(state.bowlers,key,groups,opponents);for(const key of SUNDAY_KEYS)state.brackets[key]=sunday[key];state.generated=Object.values(state.brackets).some(x=>x.length);const total=SUNDAY_KEYS.reduce((n,key)=>n+state.brackets[key].length,0);scheduleSave();render();notice(total+' Sunday brackets generated. Saturday brackets and results were preserved. Saving to Neon…');await flushSave();const confirmed=await api('/state?id='+encodeURIComponent(competition.id)),saturdayKept=SATURDAY_KEYS.every(key=>JSON.stringify(confirmed?.brackets?.[key]||[])===JSON.stringify(state.brackets[key])),sundaySaved=SUNDAY_KEYS.every(key=>JSON.stringify(confirmed?.brackets?.[key]||[])===JSON.stringify(state.brackets[key]));if(!saturdayKept||!sundaySaved)throw new Error('Neon did not return the complete Sunday draw.');notice(total+' Sunday brackets generated and verified. Saturday remains unchanged.');}catch(e){notice('Sunday brackets could not be verified as saved: '+e.message,true);}finally{button.disabled=false;}});
$('lockSaturday').addEventListener('click',async()=>{if(state.saturdayLocked)return;if(!confirm('Lock Saturday games 1–4 and all Saturday brackets? This protection cannot be removed from the app.'))return;try{state.saturdayLocked=true;scheduleSave();render();notice('Locking Saturday scores and brackets…');await flushSave();const confirmed=await api('/state?id='+encodeURIComponent(competition.id));if(!confirmed?.saturdayLocked)throw new Error('The lock was not confirmed by Neon.');notice(tr('Saturday games 1–4 and their brackets are permanently protected. Only Sunday scores can be added.'));}catch(e){state.saturdayLocked=false;render();notice('Saturday could not be locked: '+e.message,true);}});
$('scoreRows').addEventListener('change',e=>{if(!e.target.dataset.score)return;const value=e.target.value===''?null:Number(e.target.value);if(value!==null&&(!Number.isInteger(value)||value<0||value>300)){renderScores();return notice('Enter a score from 0 to 300.',true);}bowler(e.target.dataset.score).scores[Number(e.target.dataset.game)]=value;scheduleSave();renderBrackets();renderHigh();renderTeams();renderReports();});
$('teamForm').addEventListener('submit',e=>{e.preventDefault();const find=name=>state.bowlers.find(b=>b.name.toLowerCase()===name.trim().toLowerCase()),a=find($('team1').value),b=find($('team2').value);if(!a||!b){$('teamHelp').textContent='Please register bowler.';return;}if(a.id===b.id||!a.events.doubles||!b.events.doubles){$('teamHelp').textContent='Select two different bowlers registered for Doubles.';return;}if(state.teams.some(x=>x.includes(a.id)&&x.includes(b.id))){$('teamHelp').textContent='This team is already registered.';return;}state.teams.push([a.id,b.id]);$('teamHelp').textContent='';e.target.reset();scheduleSave();render();});
$('teamResults').addEventListener('click',e=>{const b=e.target.closest('[data-remove-team]');if(!b)return;state.teams.splice(Number(b.dataset.removeTeam),1);scheduleSave();render();});
$('printReport').addEventListener('click',printPayoutReport);
$('printBracketResults').addEventListener('click',printBracketResults);

(async()=>{translate();try{const r=await client.auth.getSession();await identify(r.data?.user);}catch(e){user=null;needsSessionReset=true;notice('Session expired. Log in again.',true);show('authView');translate();}})();

export {fresh,maxBrackets,buildBrackets,bracketResult,rankedAwards};
